def compile_design(design, design_path):
    """Compile design with clang++ to verify syntax"""
    print(f"  Compiling design with clang++...")

    src_dir = design_path / "src"
    compile_log_path = design_path / "compile_log.txt"

    # Build compile command
    sources = [str(src_dir / s) for s in design.get('sources', [])]

    cmd = [
        'clang++',
        '-c',  # Compile only
        '-std=c++17',
        '-I', str(src_dir / 'stubs'),
        '-D__SYNTHESIS__',
        '-w',  # Suppress warnings for cleaner output
    ] + sources + ['-o', str(design_path / f"{design['name']}.o")]

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=60,
            cwd=str(design_path)
        )

        with open(compile_log_path, 'w') as f:
            f.write(f"Compilation command: {' '.join(cmd)}\\n")
            f.write(f"Return code: {result.returncode}\\n\\n")
            f.write("STDOUT:\\n")
            f.write(result.stdout)
            f.write("\\nSTDERR:\\n")
            f.write(result.stderr)

        if result.returncode == 0:
            print(f"  ✓ Compilation successful")
            return True
        else:
            print(f"  ✗ Compilation failed (see compile_log.txt)")
            return False

    except subprocess.TimeoutExpired:
        with open(compile_log_path, 'w') as f:
            f.write("Compilation timed out after 60 seconds\\n")
        print(f"  ✗ Compilation timeout")
        return False
    except Exception as e:
        with open(compile_log_path, 'w') as f:
            f.write(f"Compilation error: {str(e)}\\n")
        print(f"  ✗ Compilation error: {e}")
        return False

