        '-D__SYNTHESIS__',
        '-w',  # Suppress warnings for cleaner output
    ] + sources + ['-o', str(design_path / f"{design['name']}.o")]

    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=60,
            cwd=str(design_path)
        )

        with open(compile_log_path, 'w') as f:
            f.write(f"Compilation command: {' '.join(cmd)}\\n")
